def count_substrings_with_at_least_k_occurrences(s, k):
    class State:
        __slots__=('next','link','len','occ')
        def __init__(self):
            self.next={}
            self.link=-1
            self.len=0
            self.occ=0
    st=[State()]
    last=0
    for ch in s:
        cur=len(st)
        st.append(State())
        st[cur].len=st[last].len+1
        st[cur].occ=1
        p=last
        while p!=-1 and ch not in st[p].next:
            st[p].next[ch]=cur
            p=st[p].link
        if p==-1:
            st[cur].link=0
        else:
            q=st[p].next[ch]
            if st[p].len+1==st[q].len:
                st[cur].link=q
            else:
                clone=len(st)
                st.append(State())
                st[clone].len=st[p].len+1
                st[clone].next=st[q].next.copy()
                st[clone].link=st[q].link
                st[clone].occ=0
                while p!=-1 and st[p].next.get(ch, -1)==q:
                    st[p].next[ch]=clone
                    p=st[p].link
                st[q].link=st[cur].link=clone
        last=cur
    order=sorted(range(len(st)), key=lambda i: st[i].len, reverse=True)
    for v in order:
        if st[v].link!=-1:
            st[st[v].link].occ+=st[v].occ
    ans=0
    for i in range(1,len(st)):
        if st[i].occ>=k:
            ans+=st[i].len-st[st[i].link].len
    return ans
